```python
"""Abstraction function and business invariants for rq, computed from a Redis snapshot.

The business-level view is what a user of rq reasons about:
  * queues: the jobs waiting in each queue, in order, and the job registries
    (started / finished / failed / deferred / scheduled / canceled) for each queue
  * jobs: status, queue, worker, timing milestones, dependencies, retry state, latest result
  * results: the history of execution outcomes per job
  * workers: state, current job, success and failure counts
  * executions: which workers are currently running which job
"""

import json

_STATUSES = (
    "created", "queued", "finished", "failed", "started",
    "deferred", "scheduled", "stopped", "canceled",
)

_REGISTRY_PREFIXES = (
    ("rq:wip:", "started"),
    ("rq:finished:", "finished"),
    ("rq:failed:", "failed"),
    ("rq:deferred:", "deferred"),
    ("rq:scheduled:", "scheduled"),
    ("rq:canceled:", "canceled"),
)
_REGISTRY_KINDS = tuple(kind for _, kind in _REGISTRY_PREFIXES)

_RESULT_TYPES = {
    "1": "successful",
    "2": "failed",
    "3": "stopped",
    "4": "retried",
    "5": "max_retries_exceeded",
}


# --------------------------------------------------------------------------- helpers

def _s(x):
    if isinstance(x, str):
        return x
    if x is None:
        return ""
    return str(x)


def _int(x):
    try:
        return int(_s(x))
    except Exception:
        return None


def _str_list(v):
    if not isinstance(v, list):
        return []
    return [_s(x) for x in v]


def _zset_members(v):
    out = []
    if isinstance(v, list):
        for item in v:
            if isinstance(item, (list, tuple)) and item:
                out.append(_s(item[0]))
            elif isinstance(item, str):
                out.append(item)
    return out


def _job_id_of(entry):
    # Started registry entries are "<job_id>:<execution_id>"; others are plain job ids.
    entry = _s(entry)
    return entry.split(":", 1)[0] if ":" in entry else entry


def _status_of(h):
    return _s(h.get("status")) or "created"


def _dependency_ids(h):
    raw = h.get("dependency_ids")
    if raw:
        try:
            parsed = json.loads(_s(raw))
            if isinstance(parsed, list):
                return [_s(x) for x in parsed]
        except Exception:
            pass
    single = h.get("dependency_id")
    return [_s(single)] if single else []


def _parse(snap):
    if not isinstance(snap, dict):
        snap = {}
    p = {
        "jobs": {},           # job id -> (hash, has_expiry)
        "dependents": {},     # job id -> [dependent ids]
        "queue_lists": {},    # queue -> [job ids] in order
        "intermediate": {},   # queue -> [job ids] dequeued but not yet started
        "known_queues": set(),
        "registries": {},     # queue -> kind -> [raw members]
        "workers": {},        # name -> hash
        "results": {},        # job id -> [stream entries]
        "exec_hashes": {},    # job id -> {execution id: worker}
        "exec_ids": {},       # job id -> [execution ids]
    }
    for key in sorted(k for k in snap if isinstance(k, str)):
        e = snap.get(key)
        if not isinstance(e, dict):
            continue
        t = e.get("t")
        v = e.get("v")

        if key.startswith("rq:job:"):
            rest = key[len("rq:job:"):]
            if t == "hash" and rest and ":" not in rest and isinstance(v, dict):
                p["jobs"][rest] = (v, bool(e.get("ttl")))
            elif t == "set" and rest.endswith(":dependents"):
                jid = rest[: -len(":dependents")]
                if jid and ":" not in jid:
                    p["dependents"][jid] = sorted(set(_str_list(v)))

        elif key.startswith("rq:queue:"):
            rest = key[len("rq:queue:"):]
            if t == "list" and rest:
                if ":" not in rest:
                    p["queue_lists"][rest] = _str_list(v)
                elif rest.endswith(":intermediate"):
                    name = rest[: -len(":intermediate")]
                    if name and ":" not in name:
                        p["intermediate"][name] = _str_list(v)

        elif key == "rq:queues":
            if t == "set":
                for m in _str_list(v):
                    if m.startswith("rq:queue:") and len(m) > len("rq:queue:"):
                        p["known_queues"].add(m[len("rq:queue:"):])

        elif key.startswith("rq:worker:"):
            name = key[len("rq:worker:"):]
            if t == "hash" and name and isinstance(v, dict):
                p["workers"][name] = v

        elif key.startswith("rq:results:"):
            jid = key[len("rq:results:"):]
            if t == "stream" and jid:
                p["results"][jid] = [x for x in v if isinstance(x, dict)] if isinstance(v, list) else []

        elif key.startswith("rq:execution:"):
            rest = key[len("rq:execution:"):]
            if t == "hash" and ":" in rest and isinstance(v, dict):
                jid, xid = rest.split(":", 1)
                if jid and xid:
                    p["exec_hashes"].setdefault(jid, {})[xid] = _s(v.get("worker_name")) or None

        elif key.startswith("rq:executions:"):
            jid = key[len("rq:executions:"):]
            if t == "zset" and jid:
                p["exec_ids"][jid] = _zset_members(v)

        else:
            for prefix, kind in _REGISTRY_PREFIXES:
                if key.startswith(prefix) and t == "zset":
                    name = key[len(prefix):]
                    if name:
                        p["registries"].setdefault(name, {})[kind] = _zset_members(v)
                    break

    # Registry contents as sets of job ids.
    reg_ids = {}
    for name, kinds in p["registries"].items():
        reg_ids[name] = {kind: {_job_id_of(m) for m in members} for kind, members in kinds.items()}
    p["reg_ids"] = reg_ids
    return p


def _all_queue_names(p):
    names = set(p["known_queues"]) | set(p["queue_lists"]) | set(p["intermediate"]) | set(p["registries"])
    for h, _ in p["jobs"].values():
        origin = _s(h.get("origin"))
        if origin:
            names.add(origin)
    return sorted(names)


def _result_view(entry):
    rtype = _s(entry.get("type"))
    view = {
        "type": _RESULT_TYPES.get(rtype, "type_" + rtype if rtype else "unknown"),
        "worker": _s(entry.get("worker_name")) or None,
        "execution": _s(entry.get("execution_id")) or None,
        "has_return_value": bool(entry.get("return_value")),
    }
    exc = entry.get("exc_string")
    view["error"] = _s(exc) if exc else None
    return view


def _executions(p):
    out = {}
    for jid in sorted(set(p["exec_hashes"]) | set(p["exec_ids"])):
        hashes = p["exec_hashes"].get(jid, {})
        ids = set(hashes) | set(p["exec_ids"].get(jid, []))
        out[jid] = [{"id": xid, "worker": hashes.get(xid)} for xid in sorted(ids)]
    return out


# --------------------------------------------------------------------------- abstraction

def abstract(snap: dict) -> dict:
    """Business-level state, as {variable name: JSON-serialisable value}."""
    p = _parse(snap)

    queues = {}
    for name in _all_queue_names(p):
        q = {
            "registered": name in p["known_queues"],
            "waiting": list(p["queue_lists"].get(name, [])),
            "being_dequeued": list(p["intermediate"].get(name, [])),
        }
        regs = p["reg_ids"].get(name, {})
        for kind in _REGISTRY_KINDS:
            q[kind] = sorted(regs.get(kind, set()))
        queues[name] = q

    results = {}
    for jid in sorted(p["results"]):
        results[jid] = [_result_view(e) for e in p["results"][jid]]

    jobs = {}
    for jid in sorted(p["jobs"]):
        h, has_ttl = p["jobs"][jid]
        timeout_raw = h.get("timeout")
        timeout = _int(timeout_raw)
        if timeout is None and timeout_raw:
            timeout = _s(timeout_raw)
        callbacks = {}
        for cb in ("success", "failure", "stopped"):
            name = _s(h.get(cb + "_callback_name"))
            if name:
                callbacks["on_" + cb] = name
        job_results = results.get(jid, [])
        jobs[jid] = {
            "status": _status_of(h),
            "queue": _s(h.get("origin")) or None,
            "description": _s(h.get("description")) or None,
            "worker": _s(h.get("worker_name")) or None,
            "enqueued": bool(h.get("enqueued_at")),
            "started": bool(h.get("started_at")),
            "ended": bool(h.get("ended_at")),
            "will_expire": has_ttl,
            "timeout": timeout,
            "retries_left": _int(h.get("retries_left")),
            "retries_done": _int(h.get("number_of_retries")),
            "repeats_left": _int(h.get("repeats_left")),
            "depends_on": _dependency_ids(h),
            "dependents": list(p["dependents"].get(jid, [])),
            "group": _s(h.get("group_id")) or None,
            "callbacks": callbacks,
            "latest_result": job_results[-1]["type"] if job_results else None,
        }

    workers = {}
    for name in sorted(p["workers"]):
        w = p["workers"][name]
        workers[name] = {
            "state": _s(w.get("state")) or None,
            "current_job": _s(w.get("current_job")) or None,
            "successful_jobs": _int(w.get("successful_job_count")) or 0,
            "failed_jobs": _int(w.get("failed_job_count")) or 0,
        }

    return {
        "queues": queues,
        "jobs": jobs,
        "results": results,
        "workers": workers,
        "executions": _executions(p),
    }


# --------------------------------------------------------------------------- invariants

def invariants(snap: dict) -> dict:
    """Business invariants, as {invariant name: bool}; True means it holds."""
    p = _parse(snap)
    jobs = p["jobs"]
    status = {jid: _status_of(h) for jid, (h, _) in jobs.items()}
    origin = {jid: _s(h.get("origin")) for jid, (h, _) in jobs.items()}

    def in_registry(jid, kind):
        return jid in p["reg_ids"].get(origin[jid], {}).get(kind, set())

    def with_status(*sts):
        return [jid for jid in sorted(jobs) if status[jid] in sts]

    def latest_result_type(jid):
        entries = p["results"].get(jid) or []
        return _s(entries[-1].get("type")) if entries else None

    inv = {}

    inv["every_job_has_a_known_status"] = all(s in _STATUSES for s in status.values())

    # Jobs waiting in a queue (and still existing) are queued, in the queue they were enqueued to.
    waiting = [(name, jid) for name in sorted(p["queue_lists"]) for jid in p["queue_lists"][name]]
    inv["jobs_waiting_in_a_queue_are_queued"] = all(
        status[jid] == "queued" for _, jid in waiting if jid in jobs
    )
    inv["jobs_wait_in_the_queue_they_were_enqueued_to"] = all(
        origin[jid] == name for name, jid in waiting if jid in jobs
    )

    # A job occupies at most one waiting position across all queues.
    seen = {}
    for lists in (p["queue_lists"], p["intermediate"]):
        for name in lists:
            for jid in lists[name]:
                seen[jid] = seen.get(jid, 0) + 1
    inv["no_job_waits_in_more_than_one_place"] = all(n <= 1 for n in seen.values())

    inv["queues_holding_jobs_are_registered"] = all(
        name in p["known_queues"] for name, lst in p["queue_lists"].items() if lst
    )

    # Each status is reflected in the matching registry of the job's queue.
    inv["started_jobs_are_in_started_registry"] = all(
        in_registry(jid, "started") for jid in with_status("started")
    )
    inv["started_jobs_record_their_worker"] = all(
        bool(_s(jobs[jid][0].get("worker_name"))) for jid in with_status("started")
    )
    inv["finished_jobs_are_in_finished_registry"] = all(
        in_registry(jid, "finished") for jid in with_status("finished")
    )
    inv["finished_jobs_have_an_end_time"] = all(
        bool(_s(jobs[jid][0].get("ended_at"))) for jid in with_status("finished")
    )
    inv["finished_jobs_have_a_successful_latest_result"] = all(
        latest_result_type(jid) == "1" for jid in with_status("finished")
    )
    inv["failed_and_stopped_jobs_are_in_failed_registry"] = all(
        in_registry(jid, "failed") for jid in with_status("failed", "stopped")
    )
    inv["deferred_jobs_are_in_deferred_registry"] = all(
        in_registry(jid, "deferred") for jid in with_status("deferred")
    )
    inv["scheduled_jobs_are_in_scheduled_registry"] = all(
        in_registry(jid, "scheduled") for jid in with_status("scheduled")
    )
    inv["canceled_jobs_are_in_canceled_registry"] = all(
        in_registry(jid, "canceled") for jid in with_status("canceled")
    )

    # A canceled job stays canceled. This is violated when a running job is canceled and the
    # worker then completes it anyway: it is listed as canceled but has status finished.
    canceled_listed = [
        jid
        for name in sorted(p["reg_ids"])
        for jid in sorted(p["reg_ids"][name].get("canceled", set()))
    ]
    inv["canceled_jobs_stay_canceled"] = all(
        status[jid] == "canceled" for jid in canceled_listed if jid in jobs
    )

    # A job is executed by at most one worker at a time.
    inv["no_job_runs_more_than_once_at_a_time"] = all(
        len(execs) <= 1 for execs in p["exec_hashes"].values()
    )

    return inv
